import{useState}from'react';import{Link}from'react-router-dom';import{Minus,Plus,Trash2,ArrowRight,Lock,ShieldCheck,Truck,CreditCard,Landmark,FileText,Check,ChevronLeft,Tag}from'lucide-react';import{useStore}from'../context/Store';import{products}from'../data/products';import ProductCard from'../components/ProductCard';import BrandLogo from'../components/BrandLogo';import{getCommerceSettings,appendAdminRow}from'../data/siteConfig';
export default function Cart({checkout=false}:{checkout?:boolean}){const{cart,setQty,remove,user,showToast}=useStore();const subtotal=cart.reduce((a,x)=>a+x.product.price*x.product.casePack*x.qty,0);if(!cart.length)return <div className="empty cart-empty"><span>0</span><h1>Your order is empty</h1><p>Explore the wholesale catalog and add products by the case.</p><Link className="btn dark" to="/shop">Browse catalog</Link></div>;if(checkout)return <Checkout subtotal={subtotal}/>;return <div className="cart-page container"><div className="cart-title"><p>WHOLESALE ORDER WORKSPACE</p><h1>Review your sourcing list</h1><span>{cart.length} line items · {cart.reduce((a,x)=>a+x.qty,0)} total cases</span></div><div className="cart-assurance"><ShieldCheck/><div><b>Protected business checkout</b><span>Documented order terms, secure payment architecture and account support through fulfillment.</span></div><Link to="/policies">View buyer protection</Link></div><div className="cart-layout"><section><div className="cart-table-head"><span>PRODUCT</span><span>CASES</span><span>TOTAL</span></div>{cart.map(({product:p,qty})=><article className="cart-item" key={p.id}><div className="cart-pic"><img src={p.image} alt={p.name}/></div><div className="cart-desc"><BrandLogo brand={p.brand} variant="micro" showName/><Link to={'/products/'+p.slug}>{p.name}</Link><small>SKU {p.sku} · {p.size} · Case of {p.casePack}</small><span className="ready-label"><Truck/> Ready to ship from US inventory</span><button onClick={()=>remove(p.id)}><Trash2/> Remove</button></div><div className="cart-qty"><small>CASES</small><div className="qty"><button onClick={()=>setQty(p.id,qty-1)}><Minus/></button><span>{qty}</span><button onClick={()=>setQty(p.id,qty+1)}><Plus/></button></div><small>{qty*p.casePack} units</small></div><div className="line-price"><b>${(p.price*p.casePack*qty).toFixed(2)}</b><small>${p.price.toFixed(2)} / unit</small></div></article>)}</section><Summary subtotal={subtotal}/></div><section className="cart-suggestions"><div className="section-head"><div><span className="eyebrow">COMPLETE YOUR ORDER</span><h2>Frequently sourced together</h2></div></div><div className="product-grid home-products">{products.slice(20,24).map(p=><ProductCard key={p.id} p={p}/>)}</div></section></div>}
function Checkout({subtotal}:{subtotal:number}){const[commerce]=useState(getCommerceSettings);const{cart,user,showToast}=useStore();const[step,setStep]=useState(1);const[done,setDone]=useState(false);const[ship,setShip]=useState('ground');const[pay,setPay]=useState('card');const[terms,setTerms]=useState(false);const[orderRef]=useState(()=>`MS-${Math.floor(10000+Math.random()*89999)}`);const shipping=ship==='expedited'?149:ship==='freight'?89:49;const tax=0;const total=subtotal+shipping+tax;if(done)return <div className="order-success container"><span><Check/></span><p className="eyebrow">ORDER REQUEST RECEIVED</p><h1>Thank you. Your order is now being reviewed.</h1><p>Reference <b>{orderRef}</b>. A confirmation has been saved for this frontend demonstration.</p><div className="success-grid"><div><b>Next step</b><span>Account and inventory review</span></div><div><b>Estimated response</b><span>Within one business day</span></div><div><b>Payment status</b><span>Not charged · mock checkout</span></div></div><Link className="btn dark" to="/account">Go to buyer dashboard</Link></div>;const next=()=>{if(step===1&&user.status==='guest'){showToast('You may continue as a demo guest buyer')}if(step<4)setStep(step+1);else if(subtotal<commerce.minimumOrder)showToast(`Minimum merchandise order is $${commerce.minimumOrder.toFixed(2)}`);else if(!terms)showToast('Accept the order terms to continue');else{appendAdminRow('orders',[orderRef,user.name||'Guest business',new Date().toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric'}),'Review',`$${total.toFixed(2)}`]);setDone(true)}};return <div className="checkout-shell"><div className="checkout-top container"><Link to="/cart"><ChevronLeft/> Back to cart</Link><span><Lock/> Secure wholesale checkout</span></div><div className="checkout-progress container">{['Business & shipping','Delivery','Payment','Review'].map((x,i)=><div className={(step===i+1?'active ':'')+(step>i+1?'done':'')} key={x}><span>{step>i+1?<Check/>:i+1}</span><b>{x}</b></div>)}</div><div className="checkout container"><div className="checkout-form"><p className="eyebrow">STEP {step} OF 4</p><h1>{['Where should we deliver?','Choose a delivery method','Select payment method','Review and submit'][step-1]}</h1>{step===1&&<><div className="account-callout"><ShieldCheck/><div><b>{user.status==='approved'?'Approved wholesale account':'Guest checkout demonstration'}</b><span>{user.status==='approved'?`${user.name} · ${user.tier} pricing active`:'Sign in to apply account pricing and saved addresses.'}</span></div>{user.status==='guest'&&<Link to="/login">Sign in</Link>}</div><h3>Business contact</h3><div className="form-grid"><label>Legal business name<input defaultValue={user.name==='Guest'?'':user.name} required/></label><label>Buyer name<input required/></label><label>Business email<input type="email" required/></label><label>Phone number<input required/></label></div><h3>Delivery address</h3><div className="form-grid"><label className="full">Street address<input required/></label><label>City<input required/></label><label>State<select><option>Select state</option><option>New York</option><option>California</option><option>Texas</option><option>Florida</option></select></label><label>ZIP code<input required/></label><label>Country<select><option>United States</option></select></label><label className="check full"><input type="checkbox"/> Save this address to my account</label></div></>}{step===2&&<><div className="delivery-options">{[['ground',Truck,'Standard ground','3–7 business days','$49.00'],['expedited',ArrowRight,'Expedited delivery','1–3 business days','$149.00'],['freight',Landmark,'Scheduled freight','For larger palletized orders','$89.00 estimate']].map(([id,I,title,desc,price]:any)=><label className={ship===id?'active':''} key={id}><input type="radio" name="ship" checked={ship===id} onChange={()=>setShip(id)}/><I/><span><b>{title}</b><small>{desc}</small></span><strong>{price}</strong></label>)}</div><div className="delivery-note"><b>Delivery estimate</b><span>Final carrier and delivery window are confirmed after inventory review.</span></div></>}{step===3&&<><div className="payment-options">{[['card',CreditCard,'Business credit or debit card','Mock card gateway — no payment is processed'],['ach',Landmark,'ACH bank transfer','Bank verification integration ready'],['terms',FileText,'Approved payment terms','Available subject to account credit approval']].map(([id,I,title,desc]:any)=><label className={pay===id?'active':''} key={id}><input type="radio" name="pay" checked={pay===id} onChange={()=>setPay(id)}/><I/><span><b>{title}</b><small>{desc}</small></span></label>)}</div>{pay==='card'&&<div className="mock-card form-grid"><label className="full">Card number<input placeholder="•••• •••• •••• ••••"/></label><label>Name on card<input/></label><label>Expiration / CVC<input placeholder="MM / YY     CVC"/></label></div>}<h3>Purchasing information</h3><div className="form-grid"><label>Purchase order number<input placeholder="Optional"/></label><label>Tax status<select><option>Resale certificate on file</option><option>Taxable purchase</option></select></label></div></>}{step===4&&<><div className="review-block"><div><h3>Shipping to</h3><button onClick={()=>setStep(1)}>Edit</button><p>Business delivery address<br/>United States</p></div><div><h3>Delivery</h3><button onClick={()=>setStep(2)}>Edit</button><p>{ship==='expedited'?'Expedited delivery':ship==='freight'?'Scheduled freight':'Standard ground'}</p></div><div><h3>Payment</h3><button onClick={()=>setStep(3)}>Edit</button><p>{pay==='card'?'Business card · mock':pay==='ach'?'ACH bank transfer':'Approved payment terms'}</p></div></div><h3>Products</h3>{cart.map(x=><div className="checkout-item" key={x.product.id}><img src={x.product.image}/><span><b>{x.product.name}</b><small>{x.qty} cases · {x.qty*x.product.casePack} units</small></span><strong>${(x.product.price*x.product.casePack*x.qty).toFixed(2)}</strong></div>)}<label className="terms-check"><input type="checkbox" checked={terms} onChange={e=>setTerms(e.target.checked)}/> I agree to the wholesale order terms, returns policy and mock payment authorization.</label></>}<div className="checkout-actions">{step>1&&<button className="btn outline" onClick={()=>setStep(step-1)}>Back</button>}<button className="btn dark" onClick={next}>{step===4?'Submit order request':'Continue'} <ArrowRight/></button></div></div><Summary subtotal={subtotal} shipping={shipping} total={total} checkout/></div></div>}
function Summary({subtotal,shipping=0,total=subtotal,checkout=false}:{subtotal:number;shipping?:number;total?:number;checkout?:boolean}){const[commerce]=useState(getCommerceSettings);const[promo,setPromo]=useState('');const[promoMessage,setPromoMessage]=useState('');const below=subtotal<commerce.minimumOrder;return <aside className="summary"><h3>Order summary</h3><div><span>Merchandise subtotal</span><b>${subtotal.toFixed(2)}</b></div><div><span>Shipping</span><em>{checkout?`$${shipping.toFixed(2)}`:'Calculated at checkout'}</em></div><div><span>Estimated tax</span><em>Certificate dependent</em></div><div className="promo-code"><Tag/><input value={promo} onChange={e=>setPromo(e.target.value)} placeholder="Promo or contract code"/><button type="button" onClick={()=>setPromoMessage(promo.trim()?`Code ${promo.toUpperCase()} recorded for order review`:'Enter a code first')}>Apply</button></div>{promoMessage&&<small className="promo-message">{promoMessage}</small>}<hr/><div className="total"><span>Estimated total</span><b>${total.toFixed(2)}</b></div><p>Final tax, freight and inventory are confirmed before fulfillment.</p>{!checkout&&(below?<button className="btn dark full" disabled>Minimum order ${commerce.minimumOrder.toFixed(2)}</button>:<Link className="btn dark full" to="/checkout">Proceed to secure checkout <ArrowRight/></Link>)}<span className="secure"><Lock/> Encrypted business checkout</span><div className="summary-protection"><ShieldCheck/><span><b>Order protection</b>Support for documented product, quantity and delivery terms.</span></div></aside>}
